import java.util.*;

class Solution {
    public int[] removeDuplicates(int[] nums) {
        int k = 1; // nums[0] is always kept
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] != nums[k - 1]) { // first copy of a new value
                nums[k] = nums[i];
                k++;
            }
        }
        return Arrays.copyOf(nums, k);
    }
}

